class DiscountCalculator:
    def calculate(self, base_price: float, discount_rate: float) -> float:
        """Calculate discounted price."""
        if discount_rate < 0 or discount_rate > 100:
            raise ValueError("Discount rate must be between 0 and 100")
        return base_price * (1 - discount_rate / 100)


def apply_discount(price: float, percent: float) -> float:
    """Apply discount percentage to price and return discounted price rounded to 2 decimal places."""
    if percent < 0 or percent > 100:
        raise ValueError("Discount percent must be between 0 and 100")
    discounted = price * (1 - percent / 100)
    return round(discounted, 2)
